export function parseMeters(value){if(value===undefined||value===null)return null;const s=String(value).trim();const imperial=s.match(/^(\d+(?:\.\d+)?)\s*['′]\s*(?:(\d+(?:\.\d+)?)\s*["″])?$/);if(imperial){const feet=Number(imperial[1]),inches=Number(imperial[2]||0),n=feet*.3048+inches*.0254;return inches<12&&n<1000?n:null;}const m=s.match(/^(\d+(?:[.,]\d+)?)\s*(m|ft)?$/i);if(!m)return null;const n=Number(m[1].replace(',','.'))*(m[2]?.toLowerCase()==='ft'?.3048:1);return Number.isFinite(n)&&n>=0&&n<1000?n:null;}
export function buildingHeight(p){const n=parseMeters(p.height);return n>0?n:null;}
export function buildingMinimum(p){return p.min_height===undefined?0:parseMeters(p.min_height);}
export function terrainBase(values){const v=values.length>1?values.slice(0,-1):values;return v.reduce((a,b)=>a+b,0)/v.length;}

export function volumeReason(properties,{mode='height',customHeight,customMode}={}){if(customHeight===undefined&&mode!=='height'&&!customMode)return 'outline_mode';const h=customHeight??buildingHeight(properties);if(h===null)return properties.height===undefined||properties.height===null||String(properties.height).trim()===''?'missing_height':'invalid_height';const min=buildingMinimum(properties);if(min===null)return 'invalid_min_height';if(min>=h)return 'min_height_conflict';return null;}
export const isBuildingPart=f=>!!f.properties?.['building:part']&&f.properties['building:part']!=='no';
export const isBuildingFeature=f=>!f.properties?.tainted&&((!!f.properties?.building&&f.properties.building!=='no')||isBuildingPart(f));
export function pointInRing(p,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[j],b=ring[i],cross=(p[0]-a[0])*(b[1]-a[1])-(p[1]-a[1])*(b[0]-a[0]);if(Math.abs(cross)<1e-12&&p[0]>=Math.min(a[0],b[0])-1e-12&&p[0]<=Math.max(a[0],b[0])+1e-12&&p[1]>=Math.min(a[1],b[1])-1e-12&&p[1]<=Math.max(a[1],b[1])+1e-12)return 2;if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside?1:0;}
export function pointInPolygon(p,poly){return pointInRing(p,poly[0])!==0&&!poly.slice(1).some(h=>pointInRing(p,h)===1);}
function intersects(a,b,c,d){const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);return cross(a,b,c)*cross(a,b,d)<0&&cross(c,d,a)*cross(c,d,b)<0;}
export function polygonContained(part,parent){if(!part[0].every(p=>pointInPolygon(p,parent)))return false;for(const r of part)for(let i=0;i<r.length-1;i++){const a=r[i],b=r[i+1];if(!pointInPolygon([(a[0]+b[0])/2,(a[1]+b[1])/2],parent))return false;for(const h of parent)for(let j=0;j<h.length-1;j++)if(intersects(a,b,h[j],h[j+1]))return false;}for(const hole of parent.slice(1)){if(hole.some(p=>pointInRing(p,part[0])===1&&!part.slice(1).some(h=>pointInRing(p,h)!==0)))return false;}return true;}
export function coordinateParts(features,{polygons,valid=()=>true,eligible=()=>true,overrides=new Map(),id=f=>String(f.id)}={}){const records=features.filter(isBuildingFeature).flatMap(f=>polygons(f).map((poly,index)=>({f,poly,index,key:id(f)+':'+index,part:isBuildingPart(f)})));const shells=records.filter(r=>!r.part&&valid(r.poly));const parts=records.filter(r=>r.part&&valid(r.poly)&&eligible(r)&&!volumeReason(r.f.properties,{customHeight:overrides.get(id(r.f))?.height}));const suppressShells=new Set(),suppressParts=new Set(),parentByPart=new Map();for(const part of parts){const parents=shells.filter(shell=>shell.f!==part.f&&polygonContained(part.poly,shell.poly));if(parents.length){const area=r=>Math.abs(r.poly[0].slice(0,-1).reduce((sum,p,i)=>{const q=r.poly[0][i+1];return sum+p[0]*q[1]-q[0]*p[1]},0));parentByPart.set(part.key,[...parents].sort((a,b)=>area(a)-area(b))[0]);}const customParent=parents.find(r=>eligible(r)&&overrides.get(id(r.f))?.mode==='box'&&!volumeReason(r.f.properties,{customHeight:overrides.get(id(r.f))?.height}));if(customParent)suppressParts.add(part.key);else for(const parent of parents)suppressShells.add(parent.key);}return {records,suppressShells,suppressParts,parentByPart};}

